/** Platform-resolved glass constants. */
export const glass = {
  panelRadius: radius["2xl"],
  cardRadius: radius.l,
  blurIntensity: Platform.OS === "android" ? blur["panel-android"] : blur["panel-ios"],
  cardBlurIntensity: Platform.OS === "android" ? blur["card-android"] : blur["card-ios"],
  tabBarBlurIntensity: Platform.OS === "android" ? blur["bar-android"] : blur["bar-ios"],
  /** Android only renders a visible blur through this experimental method. */
  experimentalBlurMethod: (Platform.OS === "android" ? "dimezisBlurView" : undefined) as "dimezisBlurView" | undefined,
  /** "light" tint brightens the whole Android screen; use "default" there. */
  blurTintLight: (Platform.OS === "android" ? "default" : "light") as "light" | "default",
  tint: (colors: ThemeColors) => (Platform.OS === "android" ? colors.surface["glass-android"] : colors.surface.glass),
  tintSolid: (colors: ThemeColors) => colors.surface["glass-solid"],
  barTint: (colors: ThemeColors) => (Platform.OS === "android" ? colors.surface["glass-bar-android"] : colors.surface["glass-bar"]),
  androidOverlay: (colors: ThemeColors) => colors.glass["android-overlay"],
  /** blurRadius for the blurred cover copy used behind full-screen glass on Android. */
  androidImageBlurRadius: blur["screen-android-image"],
} as const;

export interface Theme {
  name: "light" | "dark";
  colors: ThemeColors;
  spacing: typeof spacing;
  radius: typeof radius;
  size: typeof size;
  opacity: typeof opacity;
  motion: typeof motion;
  typography: typeof typography;
  shadows: typeof shadows;
  identicon: typeof identicon;
  components: typeof components;
}

export const lightTheme: Theme = { name: "light", colors: lightColors, spacing, radius, size, opacity, motion, typography, shadows, identicon, components };
export const darkTheme: Theme = {
  name: "dark",
  colors: darkColors as unknown as ThemeColors,
  spacing,
  radius,
  size,
  opacity,
  motion,
  typography,
  shadows,
  identicon: darkIdenticon as unknown as typeof identicon,
  components: darkComponents as unknown as typeof components,
};

/** Cap font scaling so mono names stay on one line; apply as maxFontSizeMultiplier on Text. */
export const maxFontSizeMultiplier = { default: 1.5, mono: 1.3, nav: 1.2 } as const;
